function normalizarTelefonoArgentina(numero) {
  if (!numero) return null;
  let d = String(numero).replace(/\D/g, '');
  if (d.startsWith('549') && d.length === 13) return d;
  if (d.startsWith('54') && d.length === 12) return '549' + d.slice(2);
  if (d.startsWith('0')) d = d.slice(1);
  if (d.startsWith('1115') && d.length === 12) d = '11' + d.slice(4);
  if (d.length === 10) return '549' + d;
  return null;
}
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/\s+/g, ' ').trim();

// Webhook entregas -> Entregas 0km (nombre, marca, sucursal, fecha y hora)
const body = $input.first().json.body || {};
const nombre = String(body.Nombre_Cliente || '').trim();
const marca = String(body.Marca || '').trim();
const sucursal = String(body.Sucursal || '').trim();
const fecha = String(body['Fecha y Hora Aproximada '] || body['Fecha y Hora Aproximada'] || '').trim();
const telefono = String(body.Celular || '').trim() || String(body.Telefono || '').trim() || null;
const phone = normalizarTelefonoArgentina(telefono);
// Igual que el workflow actual: solo FIAT y PEUGEOT.
const marcaOk = ['FIAT', 'PEUGEOT'].includes(norm(marca));

return [{ json: {
  valido: Boolean(phone && nombre && marcaOk && sucursal && fecha),
  campaign_id: 5967,
  campana: 'Entregas 0km',
  phone_number: phone,
  telefono_original: telefono,
  variables: { '1': nombre, '2': marca, '3': sucursal, '4': fecha },
} }];

